package com.bank.booking;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MeetingRoomsDemo {

    private static final Logger log = Logger.getLogger(MeetingRoomsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RoomPlanner planner = new RoomPlanner();

        // Sessions as [start, end] minutes from 9am. Several overlap.
        int[][] sessions = {{0, 30}, {5, 10}, {15, 20}, {25, 40}};

        int rooms = planner.minRooms(sessions);
        log.info(() -> "Minimum consultation rooms: " + rooms);  // 2
    }
}

