class RoomPlanner {

    private static final Logger log = Logger.getLogger(RoomPlanner.class.getName());

    int minRooms(int[][] sessions) {
        if (sessions.length == 0) return 0;

        // Sort by start time.
        java.util.Arrays.sort(sessions, java.util.Comparator.comparingInt(a -> a[0]));

        // Min-heap of end times of currently occupied rooms.
        java.util.PriorityQueue<Integer> endTimes = new java.util.PriorityQueue<>();
        int peak = 0;

        for (int[] session : sessions) {
            int start = session[0], end = session[1];
            // Free any room whose meeting already ended by this start.
            if (!endTimes.isEmpty() && endTimes.peek() <= start) {
                endTimes.poll();
            }
            endTimes.offer(end);                 // occupy a room
            peak = Math.max(peak, endTimes.size());
            final int p = peak;
            log.fine(() -> "  after [" + start + "," + end + "] rooms in use=" + p);
        }
        return peak;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
